window.RM_RELEASE={"version":"1.1.0-dev.16","production":"1.0.0","updated":"2026-10-16"};
window.RM_CHANGELOG=[{"version":"1.1.0-dev.16","date":"2026-10-16","summary":{"id":"Profil tanpa judul dengan pita identitas & sorotan kinerja; kartu Penarikan periode ini versi W-B; Geografi menampilkan \"x/y lokasi lengkap\" + \"Lihat & lengkapi\"; header halaman lain penuh seperti Home.","en":"Title-less Profile with an identity band & performance highlights; Period Withdrawals card in the W-B layout; Geography shows \"x/y complete locations\" + \"View & complete\"; other header pages use the full-width bar like Home."},"entries":[{"id":"dev16-profile","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · avatar → Profil","en":"Header · avatar → Profile"}},"title":{"id":"Profil: pita identitas, sorotan, kinerja — tetap satu layar","en":"Profile: identity band, highlights, performance — still one screen"},"detail":{"id":"Tanpa judul/subjudul halaman. Pita atas berisi foto (tanpa bayangan, bisa diatur langsung), nama, peran, kontak, dan tiga sorotan: masa kerja (sejak tanggal bergabung · jenis kontrak), pekerjaan tuntas bulan terakhir, sesi aktif. Di bawahnya: Data akun · Kinerja (batang ditangani vs tuntas per bulan, isu, cuti terpakai, status KPI) · Keamanan & tampilan. Muat penuh di 1366×768.","en":"No page title/subtitle. The top band holds the photo (no shadow, editable in place), name, role, contact and three highlights: tenure (join date · contract type), work closed last month, active sessions. Below: Account data · Performance (handled vs closed bars per month, issues, leave used, KPI status) · Security & appearance. Fits fully on 1366×768."}},{"id":"dev16-withdraw-wb","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Penarikan periode ini","en":"Dashboard · Period Withdrawals"}},"title":{"id":"Penarikan periode ini: satu batang alur status (W-B)","en":"Period Withdrawals: one status-flow bar (W-B)"},"detail":{"id":"Batang dibagi dibayar · menunggu pembayaran · menunggu pemeriksaan; angka dan jumlah pengajuan di bawah tiap bagian; kalimat tindakan \"Sisa Rp … harus dibayar sebelum 21 Sep (n hari lagi)\" dengan tombol ke daftar pengajuan. Rincian status diambil dari data pengajuan prototype (WD-091 menunggu pemeriksaan, WD-092 menunggu pembayaran).","en":"The bar splits paid · awaiting payment · awaiting review; amounts and request counts under each part; an action sentence \"Remaining Rp … must be paid before 21 Sep (n days left)\" with a button to the request list. The status split comes from the prototype requests (WD-091 awaiting review, WD-092 awaiting payment)."}},{"id":"dev16-geo","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Geografi anggota","en":"Dashboard · Member Geography"}},"title":{"id":"Geografi: \"x/y lokasi lengkap\" + \"Lihat & lengkapi\"","en":"Geography: \"x/y complete locations\" + \"View & complete\""},"detail":{"id":"Kaki kartu kini menunjukkan cincin kelengkapan lokasi dan tombol ke daftar lokasi belum lengkap, menggantikan tautan polos \"Lokasi belum lengkap · n\".","en":"The card footer now shows a location-completeness ring and a button to the incomplete-location list, replacing the plain \"Location incomplete · n\" link."}},{"id":"dev16-header","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · halaman selain Home","en":"Header · pages other than Home"}},"title":{"id":"Bar header halaman lain penuh kiri–kanan seperti Home","en":"Header bar on other pages is full-width like Home"},"detail":{"id":"Keuangan, Staf & Akses, Pengaturan, Kotak Masuk, dan Profil tidak lagi memakai bar yang menjorok dengan sudut bawah membulat (konten terlihat di tepi saat digulir).","en":"Finance, Staff & Access, Settings, Inbox and Profile no longer use an inset bar with rounded bottom corners (content showed at the edges when scrolling)."}}]},{"version":"1.1.0-dev.15","date":"2026-10-16","summary":{"id":"Profil muat satu layar (tiga kolom, tanpa gulir); ikon Kotak Masuk di menu header tepat setelah Home.","en":"Profile fits one screen (three columns, no scrolling); Inbox icon in the header menu right after Home."},"entries":[{"id":"dev15-profile","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · avatar → Profil","en":"Header · avatar → Profile"}},"title":{"id":"Profil dirapikan: satu layar tanpa gulir","en":"Profile tidied: one screen, no scrolling"},"detail":{"id":"Tiga kolom sejajar: foto & identitas · data akun (kisi dua kolom) + tampilan & bahasa · keamanan. Tombol aksi pindah ke kepala kelompok, catatan panjang jadi tooltip, foto 112 px. Diuji muat penuh pada layar 1440×1000 dan 1366×768.","en":"Three aligned columns: photo & identity · account data (two-column grid) + appearance & language · security. Action buttons moved to group headers, long notes became tooltips, 112 px photo. Verified to fit fully on 1440×1000 and 1366×768 screens."}},{"id":"dev15-inbox-icon","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Header · menu ikon","en":"Header · icon menu"}},"title":{"id":"Ikon Kotak Masuk di menu header, setelah Home","en":"Inbox icon in the header menu, after Home"},"detail":{"id":"Membuka halaman Kotak Masuk; aktif (lingkaran gelap) saat halaman terbuka dan Home tidak ikut aktif; titik merah bila ada notifikasi belum dibaca atau percakapan menunggu jawaban. Desain ulang halaman Kotak Masuk menyusul.","en":"Opens the Inbox page; active (dark circle) while the page is open and Home is not; red dot when there are unread notifications or conversations awaiting a reply. Inbox page redesign to follow."}}]},{"version":"1.1.0-dev.14","date":"2026-10-16","summary":{"id":"Chip gelap tanpa garis merah muda di ujung kanan; panah kartu ringkasan hanya bereaksi saat panah di-hover; Kotak Masuk & Profil tanpa sidebar aplikasi; Profil hanya akun; saklar disamakan dengan referensi.","en":"Dark chips without the pink right edge; summary-card arrow reacts only when the arrow is hovered; Inbox & Profile without the app sidebar; Profile is account-only; switch matched to the reference."},"entries":[{"id":"dev14-chip-edge","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · daftar pekerjaan · tema gelap","en":"Dashboard · work list · dark theme"}},"title":{"id":"Chip penanda gelap: hanya lengkung kiri yang berwarna","en":"Dark indicator chips: only the left curve is coloured"},"detail":{"id":"Penyebab garis di ujung kanan: lapisan warna kiri berulang ke kolom tepi kanan karena hanya lapisan terakhir yang memakai border-box. Semua lapisan kini border-box tanpa ulang; warna kanan dihilangkan dan bayangan dibuat lebih rendah, sehingga chip sama logikanya dengan pil metrik.","en":"Cause of the right-edge line: the left colour layer repeated into the right border column because only the last layer used border-box. All layers are now border-box with no repeat; the right colour is removed and the shadow lowered, so chips follow the same logic as the metric pill."}},{"id":"dev14-arrow-hover","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu ringkasan","en":"Dashboard · summary cards"}},"title":{"id":"Tombol panah berubah warna hanya saat panah di-hover","en":"Arrow button changes colour only when the arrow is hovered"},"detail":{"id":"Zona panah 28 px ditambahkan di atas lingkaran panah; hover pada bagian kartu lain tidak lagi mengubah panah. Klik di mana pun pada kartu tetap membuka rincian; fokus keyboard tetap menyorot panah.","en":"A 28 px arrow zone sits over the arrow circle; hovering elsewhere on the card no longer changes it. Clicking anywhere on the card still opens the detail; keyboard focus still highlights the arrow."}},{"id":"dev14-no-sidebar","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Kotak Masuk & Profil","en":"Inbox & Profile"}},"title":{"id":"Kotak Masuk & Profil sebagai halaman header, tanpa sidebar aplikasi","en":"Inbox & Profile as header pages, without the app sidebar"},"detail":{"id":"Keduanya dibuka dari header (lonceng/chat/avatar); sidebar aplikasi disembunyikan karena Kotak Masuk punya navigasinya sendiri. Profil kini hanya Akun (foto, data, tampilan & bahasa, keamanan); \"Label & akses\" dan \"Preferensi notifikasi\" dilepas untuk ditempatkan di menu lain bila diperlukan.","en":"Both open from the header (bell/chat/avatar); the app sidebar is hidden because the Inbox has its own navigation. Profile is now Account only (photo, data, appearance & language, security); \"Labels & access\" and \"Notification preferences\" are removed, to be placed elsewhere if needed."}},{"id":"dev14-switch","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Komponen · saklar","en":"Component · switch"}},"title":{"id":"Saklar disamakan dengan referensi (bevel)","en":"Switch matched to the reference (bevel)"},"detail":{"id":"Rasio 1,68 : 1; trek hijau bergradasi diagonal dengan tepi hijau gelap, bayangan dalam dari kiri-atas dan sorot dalam di bawah; knop #f3f3f3 bercincin putih tipis dengan bayangan ke kiri; bayangan luar lembut. Varian gelap disertakan.","en":"1.68 : 1 ratio; diagonal green gradient track with a dark-green edge, inner shadow from top-left and inner highlight at the bottom; #f3f3f3 knob with a thin white ring and leftward shadow; soft outer shadow. Dark variant included."}}]},{"version":"1.1.0-dev.13","date":"2026-10-16","summary":{"id":"Saklar hijau standar; Profil kiri–kanan dengan pengatur foto langsung; Kotak Masuk tiga kolom (notifikasi, tiket & label, internal); popover chat tidak lagi terpotong; kaca gelap memakai logika yang sama dengan terang.","en":"Standard green switch; left–right Profile with inline photo editor; three-column Inbox (notifications, tickets & labels, internal); chat popover no longer clipped; dark glass uses the same logic as light."},"entries":[{"id":"dev13-switch","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Profil · Preferensi notifikasi","en":"Profile · Notification preferences"}},"title":{"id":"Saklar standar: hijau saat aktif (dari referensi)","en":"Standard switch: green when on (from the reference)"},"detail":{"id":"Rasio dan warna diukur dari referensi: trek hijau bergradasi (kiri gelap → kanan terang, bayangan dalam di atas), knop putih dengan bayangan lembut, trek abu cekung saat nonaktif. Kelas .sw131 menjadi standar untuk saklar baru.","en":"Ratio and colours measured from the reference: gradient green track (dark left → light right, inner top shadow), white knob with soft shadow, recessed grey track when off. Class .sw131 is the standard for new switches."}},{"id":"dev13-profile","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · avatar → Profil","en":"Header · avatar → Profile"}},"title":{"id":"Profil kiri–kanan + atur foto langsung di kolom foto","en":"Left–right Profile + edit the photo right in the photo column"},"detail":{"id":"Kolom kiri: foto (unggah, geser untuk posisi, slider ukuran, simpan/batal, hapus) dan identitas. Kolom kanan: Data akun dalam kisi tiga kolom, Tampilan & bahasa berdampingan dengan Keamanan. Foto tersimpan sebagai potongan 256 px dan langsung dipakai avatar header & sidebar.","en":"Left column: photo (upload, drag to position, size slider, save/cancel, remove) and identity. Right column: account data in a three-column grid, Appearance & language beside Security. The photo is saved as a 256 px crop and used by the header & sidebar avatars right away."}},{"id":"dev13-inbox","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Kotak Masuk","en":"Inbox"}},"title":{"id":"Kotak Masuk tiga kolom: navigasi · daftar · detail","en":"Three-column Inbox: navigation · list · detail"},"detail":{"id":"Kiri: Notifikasi per jenis dan Percakapan (Semua · Tiket & label · Internal) dengan hitungan. Pembeda jenis: tiket = avatar label + ID + chip status; internal = gembok + tag. Tiket menampilkan tahapan dan satu linimasa berisi pesan label serta catatan internal (garis putus-putus + gembok); composer bisa beralih \"Balas ke label\" / \"Catatan internal\". Ruang internal diberi pita \"tidak terlihat oleh label\".","en":"Left: Notifications by type and Conversations (All · Tickets & labels · Internal) with counts. Type cues: ticket = label avatar + ID + status chip; internal = lock + tag. A ticket shows its stages and one timeline of label messages plus internal notes (dashed + lock); the composer switches between \"Reply to label\" / \"Internal note\". The internal room carries a \"not visible to labels\" strip."}},{"id":"dev13-popover","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Header · chat","en":"Header · chat"}},"title":{"id":"Popover chat tidak terpotong; jarak tautan & tombol tutup","en":"Chat popover no longer clipped; spacing between link & close"},"detail":{"id":"Kartu header tidak lagi overflow:hidden (lapisan atmosfer dipotong sendiri), sehingga popover tampil utuh di atas konten.","en":"The header card is no longer overflow:hidden (atmosphere layers clip themselves), so the popover shows in full above the content."}},{"id":"dev13-dark-glass","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · tema gelap","en":"Dashboard · dark theme"}},"title":{"id":"Kaca gelap = logika terang: warna hanya di lengkung ujung, bergradasi","en":"Dark glass = light logic: colour only on the end curves, graded"},"detail":{"id":"Analisis: di terang, rim atas/bawah putih opak menutup lapisan warna sehingga warna hanya tampak di lengkung kiri (kuat) & kanan (lembut). Di gelap rim tembus pandang, jadi warna terlihat mengelilingi pil seperti outline. Kini lapisan warna memudar sendiri ke atas/bawah (radial 14 px di ujung), sorot atas sangat tipis, tanpa semburat warna di isi.","en":"Analysis: in light, the opaque white top/bottom rim covers the colour layer so colour only shows on the left (strong) & right (soft) curves. In dark the rim is translucent, so colour ringed the pill like an outline. The colour layer now fades by itself towards top/bottom (14 px radial at the ends), very thin top highlight, no colour wash in the fill."}}]},{"version":"1.1.0-dev.12","date":"2026-10-16","summary":{"id":"Popover ringkas lonceng/chat kembali (+ tautan Kotak Masuk); Chat Center dua panel; Profil dirancang ulang sebagai daftar pengaturan; kaca tema gelap menyatu dengan kartu; ikon toggle hanya saat bergeser; audit Kamus Penanda.","en":"Quick bell/chat popovers are back (+ Inbox link); two-pane Chat Center; Profile redesigned as a settings list; dark glass blends with the card; toggle icon only while sliding; Indicator Guide audit."},"entries":[{"id":"dev12-popover","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · lonceng & chat","en":"Header · bell & chat"}},"title":{"id":"Popover ringkas tetap, dengan tautan \"Buka Kotak Masuk\"","en":"Quick popover kept, with an \"Open Inbox\" link"},"detail":{"id":"Lonceng dan ikon chat membuka tampilan cepat seperti semula; judul popover diberi tautan ke halaman Kotak Masuk.","en":"The bell and chat icons open the quick view as before; the popover title links to the Inbox page."}},{"id":"dev12-chat-center","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Kotak Masuk · Percakapan","en":"Inbox · Conversations"}},"title":{"id":"Chat Center: daftar thread di kiri, percakapan di kanan","en":"Chat Center: thread list on the left, conversation on the right"},"detail":{"id":"Thread = chat label, chat internal, tiket. Pencarian, saringan \"menunggu jawabanku\" (pesan terakhir bukan dariku), penanda status Kamus, gelembung pesan milikku/lawan bicara, kotak balasan (Enter mengirim, Shift+Enter baris baru). Balasan tersimpan di data lokal.","en":"Threads = label chat, internal chat, tickets. Search, \"awaiting my reply\" filter (last message not mine), Guide status indicator, my/their message bubbles, composer (Enter sends, Shift+Enter new line). Replies are stored locally."}},{"id":"dev12-profile","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · avatar → Profil","en":"Header · avatar → Profile"}},"title":{"id":"Profil dirancang ulang: kartu identitas + daftar pengaturan","en":"Profile redesigned: identity card + settings list"},"detail":{"id":"Satu kolom 820 px: kartu identitas (avatar, nama, email, chip peran & akses, tombol ubah), tab, lalu kelompok baris \"judul · keterangan · kontrol di kanan\". Formulir panjang dipindah ke drawer (ubah data, ubah kata sandi); saklar kecil untuk preferensi; tanpa ikon (i) yatim.","en":"One 820 px column: identity card (avatar, name, email, role & access chips, edit button), tabs, then groups of \"title · description · control on the right\" rows. Long forms moved to drawers (edit data, change password); small switches for preferences; no orphan (i) icons."}},{"id":"dev12-dark-glass","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · tema gelap","en":"Dashboard · dark theme"}},"title":{"id":"Kaca tema gelap menyatu dengan kartu (varian G)","en":"Dark glass blends with the card (variant G)"},"detail":{"id":"Tanpa garis rim yang terbaca, tanpa bayangan lebar; isi hanya +4 L* dari kartu; kesan kaca dari sorot atas berupa gradien lembut dan warna penanda sebagai cahaya di sisi kiri (radial), bukan garis. Ikon toggle tema hanya muncul saat knop bergeser.","en":"No readable rim line, no wide shadow; fill only +4 L* above the card; the glass feel comes from a soft gradient top highlight and the indicator colour as a glow on the left side (radial), not a line. The theme-toggle icon appears only while the knob slides."}},{"id":"dev12-kamus-audit","status":"prototype","where":{"role":"super","page":"standards9","menu":{"id":"Standar & Penanda · Kamus Penanda","en":"Standards & Indicators · Indicator Guide"}},"title":{"id":"Audit Kamus Penanda (dokumen, belum diterapkan)","en":"Indicator Guide audit (document, not applied yet)"},"detail":{"id":"prototype-rilis-musik/AUDIT-KAMUS-PENANDA.md: 8 temuan fungsi/struktur, 9 kata, 8 warna, penyesuaian ke chip kaca, dan daftar ubah/kembangkan/hapus. Menunggu keputusan pemilik untuk K5, K7, W3–W5.","en":"prototype-rilis-musik/AUDIT-KAMUS-PENANDA.md: 8 function/structure findings, 9 wording, 8 colour, alignment with glass chips, and a change/develop/remove list. Awaiting owner decisions on K5, K7, W3–W5."}}]},{"version":"1.1.0-dev.11","date":"2026-10-16","summary":{"id":"Dua halaman baru: Kotak Masuk (Notifikasi | Percakapan) dari lonceng/ikon chat, dan Profil (Akun · Label & akses · Preferensi notifikasi) dari avatar.","en":"Two new pages: Inbox (Notifications | Conversations) from the bell/chat icons, and Profile (Account · Labels & access · Notification preferences) from the avatar."},"entries":[{"id":"dev11-inbox","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · lonceng & chat → Kotak Masuk","en":"Header · bell & chat → Inbox"}},"title":{"id":"Kotak Masuk: notifikasi per hari + percakapan dalam satu halaman","en":"Inbox: notifications per day + conversations on one page"},"detail":{"id":"Lonceng dan ikon chat tidak lagi membuka popover kecil, melainkan halaman penuh dengan dua tab. Notifikasi dikelompokkan per hari, difilter per jenis (Pembayaran, Rilisan, Tiket & chat, Personal, Sistem), \"Tandai semua dibaca\", dan setiap baris mengarah ke objeknya. Percakapan memuat chat label, chat internal, dan tiket bantuan dengan penanda status dari Kamus; membuka thread memakai tampilan chat yang sudah ada.","en":"The bell and chat icons no longer open a small popover but a full page with two tabs. Notifications are grouped per day, filtered by type (Payments, Releases, Tickets & chat, Personal, System), \"Mark all read\", and every row links to its object. Conversations list label chat, internal chat and support tickets with Guide status indicators; opening a thread uses the existing chat view."}},{"id":"dev11-profile","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · avatar → Profil","en":"Header · avatar → Profile"}},"title":{"id":"Profil: halaman khusus saat avatar diklik","en":"Profile: a dedicated page when the avatar is clicked"},"detail":{"id":"Tiga tab. Akun: data akun (ubah lewat drawer yang sudah ada), tema & bahasa, ganti kata sandi (validasi: minimal 10 karakter, ulangan harus sama), sesi aktif dengan keluar dari perangkat lain. Label & akses: peran, status akses, daftar kewenangan memakai penanda Kamus. Preferensi notifikasi: kanal dalam-aplikasi / email per jenis kejadian, tersimpan di browser.","en":"Three tabs. Account: account data (edited via the existing drawer), theme & language, change password (validation: at least 10 characters, repeat must match), active sessions with sign-out of other devices. Labels & access: role, access status, permission list using Guide indicators. Notification preferences: in-app / email channel per event type, saved in the browser."}}]},{"version":"1.1.0-dev.10","date":"2026-10-16","summary":{"id":"Satu standar kaca untuk pil & chip: rim chip kini benar-benar berwarna penanda; tema gelap dirancang ulang sebagai lempeng kaca (bukan outline putih).","en":"One glass standard for pill & chip: the chip rim now truly carries the indicator colour; dark theme redesigned as a glass slab (not a white outline)."},"entries":[{"id":"dev10-chip-rim","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · daftar pekerjaan","en":"Dashboard · work list"}},"title":{"id":"Rim chip mengikuti warna penanda (perbaikan dev.9)","en":"Chip rim follows the indicator colour (dev.9 fix)"},"detail":{"id":"Di dev.9 rim chip tampak abu karena deklarasi warna penanda tertimpa aturan chip yang lebih tua; kini warna penanda (--status111) dipakai sekali untuk titik dan rim, teks tetap netral. Pil dan chip memakai satu set variabel yang sama — chip hanya versi berskala.","en":"In dev.9 the chip rim looked grey because the indicator-colour declaration was overridden by an older chip rule; now the indicator colour (--status111) is used once for the dot and the rim, text stays neutral. Pill and chip share one set of variables — the chip is just a scaled version."}},{"id":"dev10-dark-glass","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · tema gelap","en":"Dashboard · dark theme"}},"title":{"id":"Kaca tema gelap: lempeng lebih terang dari kartu, sorot atas, sisi lembut","en":"Dark-theme glass: slab brighter than the card, top highlight, soft sides"},"detail":{"id":"Analisis dev.9: isi hampir sama dengan kartu, rim putih 43 L* dan sisi berwarna 52% terbaca sebagai outline, bayangan hitam tak terlihat — tidak ada kesan kaca. Dari lima varian mock, dipilih D: isi +15 L* di atas kartu memudar ke bawah, lensa kiri kuat, sorot 1 px di dalam tepi atas, rim atas terang → bawah redup, sisi berwarna 30%/14%, bayangan hitam ke bawah (−5 L*).","en":"dev.9 analysis: fill nearly equal to the card, a 43 L* white rim and 52% coloured sides read as an outline, black shadow invisible — no glass feel. Of five mock variants, D was chosen: fill +15 L* above the card fading downward, strong left lens, 1 px inner top highlight, bright top rim → dim bottom, coloured sides 30%/14%, black downward shadow (−5 L*)."}}]},{"version":"1.1.0-dev.9","date":"2026-10-15","summary":{"id":"Bayangan kaca netral & lebih rendah; warna penanda diaudit terhadap Kamus Penanda (teks chip netral, hanya titik berwarna); toggle tema tanpa ikon; tombol header tanpa blok hover.","en":"Neutral, lower glass shadow; indicator colours audited against the Indicator Guide (neutral chip text, only the dot coloured); theme toggle without icon; header buttons without hover block."},"entries":[{"id":"dev9-shadow","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu metrik & daftar pekerjaan","en":"Dashboard · metric cards & work list"}},"title":{"id":"Bayangan pil & chip: netral dan tidak melayang","en":"Pill & chip shadow: neutral and grounded"},"detail":{"id":"Semu warna indikator pada bayangan dihapus; offset/blur dikurangi (pil 2/6 px, chip 1/4 px). Profil di bawah tepi: pil 91·94·96·97 (dev.8: 86·89·91·92), chip 93·97·97.","en":"Indicator tint removed from the shadow; offset/blur reduced (pill 2/6 px, chip 1/4 px). Profile below the edge: pill 91·94·96·97 (dev.8: 86·89·91·92), chip 93·97·97."}},{"id":"dev9-tones","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · daftar pekerjaan; Label","en":"Dashboard · work list; Labels"}},"title":{"id":"Warna penanda mengikuti Kamus Penanda; teks chip netral","en":"Indicator colours follow the Indicator Guide; neutral chip text"},"detail":{"id":"Aturan kamus: biru = menunggu/diproses, oranye = perlu tindakan, merah = lewat tenggat, hijau = selesai, netral = ditutup/kedaluwarsa. Diperbaiki: \"Baru\" dan \"Diajukan\" (tiket) tadinya netral → biru; penanda akses di halaman Label (Normal/Dibatasi/Ditangguhkan) tadinya di luar sistem status (kuning lain, tanpa titik) → netral/oranye/merah dengan titik. Pada chip kaca hanya titik dan rim yang berwarna; teks memakai warna teks biasa.","en":"Guide rule: blue = waiting/processing, orange = action needed, red = past deadline, green = done, neutral = closed/expired. Fixed: \"New\" and \"Submitted\" (tickets) were neutral → blue; access indicators on the Labels page (Normal/Limited/Suspended) sat outside the status system (different yellow, no dot) → neutral/orange/red with a dot. On glass chips only the dot and rim carry the colour; text uses the normal text colour."}},{"id":"dev9-header","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Header","en":"Header"}},"title":{"id":"Toggle tema tanpa ikon; tombol bahasa/notifikasi/chat/profil tanpa blok hover","en":"Theme toggle without icon; language/notification/chat/profile buttons without hover block"},"detail":{"id":"Ikon matahari/bulan di dalam knop disembunyikan. Latar hover pada empat tombol header dihapus; fokus keyboard tetap diberi garis luar.","en":"The sun/moon icon inside the knob is hidden. Hover background on the four header buttons removed; keyboard focus still shows an outline."}}]},{"version":"1.1.0-dev.8","date":"2026-10-15","summary":{"id":"Kaca v4: lensa di sisi kiri, rim berwarna indikator di kiri–kanan untuk pil DAN chip status, bayangan diukur ulang terhadap referensi baru.","en":"Glass v4: left-side lens, indicator-coloured rim on left/right for the pill AND status chips, shadow re-measured against the new references."},"entries":[{"id":"dev8-glass-pill","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu metrik","en":"Dashboard · metric cards"}},"title":{"id":"Pil kaca v4: lensa kiri + rim berwarna di kiri–kanan","en":"Glass pill v4: left lens + coloured rim on both sides"},"detail":{"id":"Referensi pil 15% diukur per 1 px: isi di sisi kiri lebih gelap 3 L* dari latar (lensa), rim putih di atas & bawah, warna indikator kuat di kiri dan lembut di kanan, bayangan hanya ke bawah. Hasil kami vs referensi: bayangan 86·89·91·92·93 (ref 89·91·92·93·94), garis kiri 81 (ref 82), isi kiri 94–95 (ref 95), garis kanan 94 (ref 94).","en":"The 15% reference pill measured per CSS px: left fill 3 L* darker than the page (lens), white rim top & bottom, strong indicator colour on the left and soft on the right, downward-only shadow. Ours vs reference: shadow 86·89·91·92·93 (ref 89·91·92·93·94), left line 81 (ref 82), left fill 94–95 (ref 95), right line 94 (ref 94)."}},{"id":"dev8-chips","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · daftar pekerjaan","en":"Dashboard · work list"}},"title":{"id":"Chip status memakai resep yang sama: warna indikator di sisi kiri & kanan","en":"Status chips use the same recipe: indicator colour on the left & right sides"},"detail":{"id":"Chip tidak punya pseudo-elemen bebas (::before = titik status, ::after dimatikan), jadi rim digambar lewat border transparan 1 px + lapisan border-box. Profil vs referensi chip: tepi atas putih 100, isi 99→98, bayangan 89·92·93·94 (ref 91·93·94·95). Tema gelap memakai alas kartu opak agar rim tidak tembus ke dalam chip.","en":"Chips have no free pseudo-element (::before = status dot, ::after disabled), so the rim is drawn via a 1 px transparent border + border-box layers. Profile vs the reference chip: white top 100, fill 99→98, shadow 89·92·93·94 (ref 91·93·94·95). Dark theme uses an opaque card base so the rim does not show through the chip."}}]},{"version":"1.1.0-dev.7","date":"2026-10-15","summary":{"id":"Kaca v3 yang diukur sampai cocok dengan referensi; header jadi kartu berjarak dari atas + bar kaca penuh saat scroll; toggle & slider bergaya fisik; tombol kartu seragam; kartu penarikan tanpa tombol.","en":"Glass v3 measured until it matches the reference; header as an inset card + full-width glass bar on scroll; physical toggle & switch; uniform card buttons; withdrawal card without a button."},"entries":[{"id":"dev7-glass","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu metrik","en":"Dashboard · metric cards"}},"title":{"id":"Pil kaca cocok dengan referensi (diukur)","en":"Glass pill matches the reference (measured)"},"detail":{"id":"Profil kecerahan pil dibandingkan angka per angka dengan referensi: tepi atas putih 100, isi 99→97, tepi bawah 86 (ref 89), garis kiri 81 (ref 82). Pil lebih lapang (26 px), tanpa cincin abu, bayangan hanya ke bawah.","en":"Pill brightness profile compared number by number with the reference: white top rim 100, fill 99→97, bottom edge 86 (ref 89), left line 81 (ref 82). Roomier pill (26 px), no grey ring, downward-only shadow."}},{"id":"dev7-header","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · header","en":"Dashboard · header"}},"title":{"id":"Header jadi kartu berjarak dari tepi atas","en":"Header becomes an inset card"},"detail":{"id":"Isi tetap (sapaan + Wawasan); bentuknya kartu bersudut 26 px dengan jarak 12 px dari atas & samping. Saat digulir > 140 px melipat jadi bar penuh kiri–kanan berkaca; mengembang lagi di puncak.","en":"Content unchanged (greeting + Insights); the frame is a 26 px rounded card inset 12 px from the top and sides. Scrolling past 140 px folds it into a full-width glass bar; it expands again at the top."}},{"id":"dev7-controls","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Header · toggle tema & slider Platform–Staf","en":"Header · theme toggle & Platform–Staff switch"}},"title":{"id":"Toggle tema & slider Platform–Staf bergaya fisik","en":"Physical-style theme toggle & workspace switch"},"detail":{"id":"Track cekung, knob cembung dengan sorotan & bayangan lembut, gerak memantul ringan; warna netral.","en":"Concave track, convex knob with highlight & soft shadow, slight bounce; neutral colours."}},{"id":"dev7-buttons","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu statistik & metrik","en":"Dashboard · stat & metric cards"}},"title":{"id":"Tombol buka/tutup seragam: hover hitam, chevron memantul, panel mengembang","en":"Uniform open/close buttons: black hover, bouncing chevron, expanding panel"},"detail":{"id":"Tombol metrik ikut aturan hover kartu lain (hitam di terang, putih di gelap); tombol kartu statistik & tenggat memakai animasi yang sama. Kartu Penarikan periode ini tidak lagi punya tombol rincian.","en":"The metric button follows the other cards' hover rule (black in light, white in dark); stat and deadline card buttons use the same animation. The period-withdrawal card no longer has a details button."}}]},{"version":"1.1.0-dev.6","date":"2026-10-15","summary":{"id":"Resep kaca ditulis ulang dari profil piksel referensi; chip status kecil di samping nama; seal label terverifikasi di mana pun; animasi buka/tutup; klik menu 2× lebih ringan.","en":"Glass recipe rebuilt from the reference pixel profile; small status chips beside the title; verified-label seal everywhere; open/close animation; menu clicks twice as light."},"entries":[{"id":"dev6-glass","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu metrik","en":"Dashboard · metric cards"}},"title":{"id":"Pil & tooltip kaca seperti referensi","en":"Glass pills & tooltips like the reference"},"detail":{"id":"Isi gradien putih (lensa), rim atas putih, semu warna hanya di sisi segitiga, bayangan lembut ke bawah; urutan segitiga lalu angka.","en":"White gradient fill (lens), white top rim, colour tint only on the triangle side, soft downward shadow; triangle before the number."}},{"id":"dev6-chips","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Antrean & Pekerjaan Saya","en":"Dashboard · Queue & My Work"}},"title":{"id":"Chip status kecil tepat setelah nama pekerjaan","en":"Small status chips right after the work title"},"detail":{"id":"11 px, resep kaca yang sama, bersemu warna statusnya.","en":"11 px, same glass recipe, tinted with the status colour."}},{"id":"dev6-seal","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · daftar pekerjaan","en":"Dashboard · work lists"}},"title":{"id":"Seal terverifikasi di mana pun nama label tampil","en":"Verified seal wherever a label name appears"},"detail":{"id":"Nama label terverifikasi (mis. Awan Records) selalu diikuti seal — daftar pekerjaan, sidebar, dialog.","en":"Verified label names are always followed by the seal — work lists, sidebar, dialogs."}},{"id":"dev6-motion","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu metrik","en":"Dashboard · metric cards"}},"title":{"id":"Animasi buka/tutup rincian metrik","en":"Metric detail open/close animation"},"detail":{"id":"Panel mengembang 380 ms, isi muncul bertahap, batang menggambar diri; tutup 200 ms; chevron memantul ringan. Mengikuti prefers-reduced-motion.","en":"Panel expands in 380 ms, content staggers in, bars draw themselves; closes in 200 ms; chevron bounces slightly. Honours prefers-reduced-motion."}},{"id":"dev6-inp","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Seluruh preview","en":"Whole preview"}},"title":{"id":"Klik menu lebih ringan: simpan ditunda 300 ms","en":"Lighter menu clicks: saves deferred by 300 ms"},"detail":{"id":"Setiap klik dulu men-serialisasi ±7 MB data (INP 400–540 ms). Kini simpan digabung 300 ms setelah aksi; transaksi atomik tetap seketika. Klik Dashboard 358 → 182 ms.","en":"Each click used to serialise ±7 MB of data (INP 400–540 ms). Saves are now batched 300 ms after the action; atomic transactions stay immediate. Dashboard click 358 → 182 ms."}}]},{"version":"1.1.0-dev.5","date":"2026-10-15","summary":{"id":"Detail kaca dari referensi pemilik: kartu lembut, pil persentase & tooltip kaca bersemu warna, progress tebal bergaris. Eksplorasi warna merek dihapus. Klik pertama di Studio kini berhasil.","en":"Glass details from the owner reference: soft cards, tinted glass percentage pills & tooltips, thick striped progress. Brand colour exploration removed. First Studio click now works."},"entries":[{"id":"dev5-card","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Kartu lembut: selisih +3 L* dari latar","en":"Soft cards: +3 L* step above the background"},"detail":{"id":"Terang #F8F8F8 di atas #F0F0F0, gelap #171718 di atas #0A0A0B — langkah kecerahan yang sama dengan referensi; tepi = garis bayangan 1 px + sorotan 1 px.","en":"Light #F8F8F8 on #F0F0F0, dark #171718 on #0A0A0B — the same perceptual step as the reference; edge = 1 px shadow line + 1 px highlight."}},{"id":"dev5-glass","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu metrik","en":"Dashboard · metric cards"}},"title":{"id":"Pil persentase kaca bersemu warna metrik","en":"Glass percentage pill tinted by the metric colour"},"detail":{"id":"Angka warna teks, segitiga hijau/merah; tepi kiri & bayangan bersemu warna yang sama. Chip status di daftar pekerjaan memakai resep yang sama.","en":"Text-coloured number, green/red triangle; left edge & shadow tinted with the same colour. Status chips in the work lists use the same recipe."}},{"id":"dev5-tooltip","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Penarikan periode ini","en":"Dashboard · Period withdrawals"}},"title":{"id":"Progress tebal bergaris + tooltip kaca","en":"Thick striped progress + glass tooltip"},"detail":{"id":"Batang 14 px bergaris diagonal hijau dengan penanda di ujung; arahkan kursor untuk “75,6% · Rp 75.000.000 dibayarkan”. Nominal ringkas di kartu metrik juga menampilkan angka lengkap saat diarahkan.","en":"14 px bar with green diagonal stripes and an end marker; hover for “75.6% · Rp 75,000,000 paid”. Abbreviated metric values also reveal the full number on hover."}},{"id":"dev5-studio-fix","status":"prototype","where":{"role":"super","page":"dashboard","theme":"dark","menu":{"id":"Studio Pratinjau","en":"Preview Studio"}},"title":{"id":"Klik pertama di Studio kini berhasil","en":"First Studio click now works"},"detail":{"id":"Titik pulih Studio (8,5 MB) melebihi kuota localStorage sehingga skenario pertama selalu gagal diam-diam — kini cukup disimpan di memori.","en":"The Studio checkpoint (8.5 MB) exceeded the localStorage quota so the first scenario always failed silently — it is now kept in memory."}}]},{"version":"1.1.0-dev.4","date":"2026-10-14","summary":{"id":"Masukan dev 3: kartu metrik ringkas dengan rincian buka/tutup, preview jauh lebih cepat, entri tema gelap di Studio diperbaiki.","en":"dev 3 feedback: compact metric cards with expandable details, much faster preview, Studio dark-theme entry fixed."},"entries":[{"id":"dev4-metric-inline","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu metrik","en":"Dashboard · metric cards"}},"title":{"id":"Rincian metrik buka/tutup di bawah kartu","en":"Metric details expand below the cards"},"detail":{"id":"Klik kartu untuk membuka perbandingan periode (tanpa popup). Kartu 20% lebih pendek; nominal besar diringkas (Rp 151,6 jt).","en":"Click a card to expand the period comparison (no popup). Cards are 20% shorter; large amounts are abbreviated."}},{"id":"dev4-speed","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Seluruh preview","en":"Whole preview"}},"title":{"id":"Preview lebih cepat, tanpa perjalanan versi","en":"Faster preview, no version run-through"},"detail":{"id":"Tampil 12,8 → 8,8 dtk (kunjungan ulang 9,8 → 6,2 dtk); setiap gambar ulang 467 → 189 ms. Judul tab & label versi tidak lagi berganti saat memuat.","en":"Shows in 8.8 s instead of 12.8 s (repeat visits 6.2 s); each re-render 189 ms instead of 467 ms. Tab title and version label no longer cycle while loading."}}]},{"version":"1.1.0-dev.3","date":"2026-10-14","summary":{"id":"Fondasi tampilan baru, diuji di Dashboard Super & Admin: font Geist, skala tulisan tanpa tebal, tema gelap lebih pekat, persentase metrik sebaris.","en":"New look foundation, trialled on the Super & Admin dashboards: Geist font, weight-light type scale, deeper dark theme, inline metric percentages."},"entries":[{"id":"dev3-type","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Font Geist + skala tulisan baru","en":"Geist font + new type scale"},"detail":{"id":"7 ukuran (12–40) dengan berat 400/500 saja; penekanan lewat ukuran & warna. Font 18 KB. Baru di Dashboard.","en":"7 sizes (12–40), weights 400/500 only; emphasis through size and colour. 18 KB font. Dashboard only for now."}},{"id":"dev3-dark","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard (tema gelap)","en":"Dashboard (dark theme)"},"theme":"dark"},"title":{"id":"Tema gelap lebih pekat","en":"Deeper dark theme"},"detail":{"id":"Latar #0A0A0B, kartu #141415 bertepi tipis — berlaku di seluruh halaman tema gelap.","en":"Background #0A0A0B, cards #141415 with a hairline border — applies to every dark-theme page."}},{"id":"dev3-metric","status":"prototype","where":{"role":"admin","page":"dashboard","menu":{"id":"Dashboard · kartu metrik","en":"Dashboard · metric cards"}},"title":{"id":"Persentase metrik di samping angka","en":"Metric percentage beside the value"},"detail":{"id":"+12% ↗ hijau, −8,1% ↘ merah, 0% → abu-abu; keterangan periode tetap di bawah.","en":"+12% ↗ green, −8.1% ↘ red, 0% → grey; the period caption stays below."}}]},{"version":"1.1.0-dev.2","date":"2026-10-14","summary":{"id":"Preview lebih ringan: berkas besar dimuat belakangan.","en":"Lighter preview: large files load later."},"entries":[{"id":"dev2-lazy-load","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Muatan awal preview turun 35%","en":"Initial preview payload down 35%"},"detail":{"id":"Data bank/wilayah dan pembuat PDF kontrak (1,4 MB) diunduh setelah tampilan muncul; tampil ±15% lebih cepat di jaringan HP.","en":"Bank/region data and the contract PDF maker (1.4 MB) download after the screen appears; about 15% faster on mobile networks."}}]},{"version":"1.1.0-dev.1","date":"2026-10-14","summary":{"id":"Titik awal v1.1: audit keamanan & uang, ikon verifikasi baru, data contoh disamarkan.","en":"v1.1 starting point: security & money audit, new verification badge, pseudonymised sample data."},"entries":[{"id":"dev1-verified-badge","status":"both","where":{"role":"super","page":"labels9","menu":{"id":"Manajemen Label","en":"Label Management"}},"title":{"id":"Ikon verifikasi label baru","en":"New label verification badge"},"detail":{"id":"Bintang datar 11 ujung sesuai referensi; centang transparan mengikuti warna latar.","en":"Flat 11-point star per the reference; the check is transparent and shows the background."}},{"id":"dev1-sample-data","status":"prototype","where":{"role":"super","page":"labels9","menu":{"id":"Manajemen Label","en":"Label Management"}},"title":{"id":"Data contoh memakai nama samaran","en":"Sample data uses pseudonyms"},"detail":{"id":"Nama label, artis, email, WA dan alamat asli diganti samaran; nominal dan status tetap.","en":"Real label, artist, email, phone and address values are replaced; amounts and statuses are kept."}},{"id":"dev1-boot","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Preview terbuka tanpa “perjalanan versi”","en":"Preview opens without the version run-through"},"detail":{"id":"Tampilan muncul sekali dalam kondisi akhir; label versi kini v1.1 · dev N.","en":"The screen appears once in its final state; the version label is now v1.1 · dev N."}},{"id":"dev1-token-addons","status":"app","where":null,"title":{"id":"Pembayaran token tidak lagi melunasi add-on","en":"Token payments no longer settle add-ons"},"detail":{"id":"Invoice berisi add-on dibayar rupiah; token hanya untuk biaya rilisan.","en":"Invoices with add-ons are paid in rupiah; tokens cover the release fee only."}},{"id":"dev1-money-guards","status":"app","where":null,"title":{"id":"Pengaman uang: bayar, refund, withdraw","en":"Money guards: pay, refund, withdraw"},"detail":{"id":"Klik ganda tidak memotong token dua kali, tidak ada refund ganda, withdraw yang sudah dibayar tidak bisa ditolak ulang.","en":"Double clicks never spend twice, no double refunds, paid withdrawals cannot be rejected again."}},{"id":"dev1-staff-preview","status":"app","where":null,"title":{"id":"Pratinjau akses staf lebih aman","en":"Safer staff access preview"},"detail":{"id":"Keluar akun berfungsi saat pratinjau; menu khusus Super Admin tersembunyi selama pratinjau.","en":"Sign-out works during preview; Super Admin-only menus stay hidden while previewing."}}]}];
